def count_bulls_and_cows(guess, candidate):
    """Return (bulls, cows) for a guess and candidate number."""
    bulls = 0
    for i in range(4):
        if guess[i] == candidate[i]:
            bulls += 1

    # Calculate cows
    # Create lists of digits that are not bulls
    guess_non_bull = [guess[i] for i in range(4) if guess[i] != candidate[i]]
    candidate_non_bull = [candidate[i] for i in range(4) if candidate[i] != guess[i]]

    # Count cows
    cows = 0
    for g in guess_non_bull:
        if g in candidate_non_bull:
            cows += 1
            candidate_non_bull.remove(g)

    return bulls, cows

def solve():
    n = int(input())
    guesses = []
    for _ in range(n):
        parts = input().split()
        guess = parts[0]
        bulls = int(parts[1])
        cows = int(parts[2])
        guesses.append((guess, bulls, cows))

    # Generate all valid 4-digit numbers with distinct digits
    valid_numbers = set()
    from itertools import permutations
    for digits in permutations(range(10), 4):
        number = ''.join(map(str, digits))
        valid_numbers.add(number)

    # Find which numbers are consistent with all guesses
    consistent_numbers = valid_numbers.copy()
    for guess, expected_bulls, expected_cows in guesses:
        new_consistent = set()
        for candidate in consistent_numbers:
            bulls, cows = count_bulls_and_cows(guess, candidate)
            if bulls == expected_bulls and cows == expected_cows:
                new_consistent.add(candidate)
        consistent_numbers = new_consistent

        # If no consistent numbers left, break early
        if not consistent_numbers:
            break

    if not consistent_numbers:
        print("Incorrect data")
    elif len(consistent_numbers) == 1:
        print(consistent_numbers.pop())
    else:
        print("Need more data")

solve()
"}

