    n = int(input())

    # Calculate answer using formula (2n)! / (2^n * n!)
    numerator = 1
    for i in range(1, 2 * n + 1):
        numerator *= i

    denominator = 1
    for i in range(1, 2 * n + 1):
        if i <= n:
            denominator *= i

    answer = numerator // denominator
    print(answer)
