import sys

def catalan(n):
    # Catalan number formula
    return (1 / (n + 1)) * binomial(2 * n, n)

def binomial(n, k):
    # Calculate binomial coefficient
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

def solve():
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    T = int(data[0])

    # Process each test case
    for i in range(1, T + 1):
        N = int(data[i])

        # Calculate answer
        answer = catalan(N)

        # Print answer
        sys.stdout.write(f"{answer}\n")

if __name__ == "__main__":
    solve()
"}

