    a = list(map(int, input().split()))

    # Try each possible left boundary l
    max_len = 0
    results = []

    for l in range(n):
        # Try to extend right boundary r
        r = l
        while True:
            # Check if there exists some element in [l, r] that divides all elements
            found = False
            for k in range(l, r + 1):
                # Check if a[k] divides all elements from a[l] to a[r]
                if all((a[i] % a[k] == 0) for i in range(l, r + 1)):
