    # dp[i] = maximum cost of a strange set that ends with element i
    dp = [-10**5 - 1] * n

    for i in range(n):
        # Option 1: just include i
        dp[i] = b[i]
        # Option 2: include i in a set that includes some previous elements
        for j in range(i):
            if a[j] != 0 and a[i] % a[j] == 0:
                # If a[j] divides a[i], we need j in the set
                if dp[j] != -10**5 - 1:
                    dp[i] = max(dp[i], dp[j] + b[i])

    print(max(dp))

