import sys

def solve():
    MOD = 998244353
    n = int(sys.stdin.readline())
    tree = [[] for _ in range(n + 1)]

    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        tree[u].append(v)
        tree[v].append(u)

    # Check if the tree is a star (all edges connected to one node)
    star_center = -1
    for i in range(1, n + 1):
        if len(tree[i]) == n - 1:
            star_center = i
            break

    if star_center != -1:
        # Star tree, any permutation works
        result = 1
        for i in range(2, n + 1):
            result = result * i % MOD
        print(result)
        return

    # Find the node with degree > 2
    for i in range(1, n + 1):
        if len(tree[i]) > 2:
            d = len(tree[i])
            break

    result = 1
    for i in range(2, n + 1):
        result = result * i % MOD

    # If degree > 2, divide by (d-1)
    if d > 2:
        result = result * pow(d - 1, MOD - 2, MOD) % MOD

    print(result)

if __name__ == "__main__":
    solve()
"}

