def is_k_balanced(s, k):
    """Check if the string s is already k-balanced"""
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i+k]
        zeros = substring.count('0')
        ones = substring.count('1')
        if zeros != ones:
            return False
    return True

def can_make_k_balanced(s, k):
    """Check if we can make the string k-balanced by replacing '?'"""
    n = len(s)

    # If already k-balanced, return True
    if is_k_balanced(s, k):
        return True

    # Check if we can make it periodic with period k/2
    period = k // 2

    # Check if the first k characters can form a pattern
    # that can be repeated
    first_k = s[:k]

    # Check if the pattern is consistent
    # If position i has value v, then position i + k must also have value v
    for i in range(k):
        for j in range(i + k, n, k):
            if first_k[i] == '0' and s[j] == '1':
                return False
            if first_k[i] == '1' and s[j] == '0':
                return False

    return True

