def is_k_balanced(s, k):
    """Check if the string s is already k-balanced"""
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i+k]
        zeros = substring.count('0')
        ones = substring.count('1')
        if zeros != ones:
            return False
    return True

def can_make_k_balanced(s, k):
    """Check if we can make the string k-balanced by replacing '?'"""
    n = len(s)

    # If already k-balanced, return True
    if is_k_balanced(s, k):
        return True

    # Check if we can make it periodic with period k
    # Position i should equal position i + k
    for i in range(n - k):
        if s[i] == '0' and s[i + k] == '1':
            return False
        if s[i] == '1' and s[i + k] == '0':
            return False

    return True

