import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Sort in descending order
    a.sort(reverse=True)

    # Try all possible number of days
    for days in range(1, n + 1):
        # Try all possible distributions of n cups across days
        # For d days, we try all possible k1, k2, ..., kd such that sum = n

        # This is a recursive depth-first search approach
        def dfs(pos, days_left, total_pages):
            if days_left == 0:
                if total_pages >= m:
                    return True
                return False

            # Try all possible ways to distribute the remaining cups
            for k in range(0, n - pos + 1):
                # Value of drinking k cups
                value = 0
                for i in range(k):
                    value += max(0, a[pos + i] - i)

                if dfs(pos + k, days_left - 1, total_pages + value):
                    return True
            return False

        if dfs(0, days, 0):
            print(days)
            return

    print(-1)

if __name__ == "__main__":
    solve()
