T = int(input())

# Initialize DP table
dp = [[0] * (m + 1) for _ in range(n + 1)]
dp[1][1] = 1

# Calculate number of paths
def count_paths():
    """Calculate the number of paths from (1, 1) to (n, m)"""
    dp[1][1] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i == 1 and j == 1:
                continue
            # Check if we can come from above
            if doors[(i-1, j)] == 0:  # door from (i-1, j) to (i, j) is open
                dp[i][j] += dp[i-1][j]
            # Check if we can come from the left
            if doors[(i, j-1)] == 0:  # door from (i, j-1) to (i, j) is open
                dp[i][j] += dp[i][j-1]
    return dp[n][m]

# Try different maze sizes until we find one that works
def solve():
    for n_size in range(1, 51):
        for m_size in range(1, 51):
            # Initialize all doors as open
            doors = {(i, j): 0 for i in range(1, n_size + 1) for j in range(1, m_size + 1)}

            # Calculate number of paths
            paths = count_paths()

            # If we have too many paths, we need to lock doors
            if paths > T:
                # Lock doors from top
                for i in range(1, n_size):
                    for j in range(1, m_size):
                        if paths > T:
                            doors[(i, j)] = 1  # Lock door from (i, j) to (i+1, j)
                            paths = count_paths()

            # If we have too few paths, we need to lock doors differently
            if paths < T:
                # Lock doors from left
                for i in range(1, n_size):
                    for j in range(1, m_size):
                        if paths < T:
                            doors[(i, j)] = 2  # Lock door from (i, j) to (i, j+1)
                            paths = count_paths()

            if paths == T:
                print(n_size, m_size)
                print(len(doors))
                for door, locked in doors.items():
                    if locked:
                        i, j = door
                        if locked == 1:
                            print(f"{i} {j} {i+1} {j}")  # Lock door from (i, j) to (i+1, j)
                        else:
                            print(f"{i} {j} {i} {j+1}")  # Lock door from (i, j) to (i, j+1)
                return

solve()
