def max_paths(n, m):
    """Returns the maximum number of paths in an n×m maze (all doors open)"""
    # This is C(n+m-2, n-1) - we'll calculate it using DP for simplicity
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[1][1] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i == 1 and j == 1:
                continue
            # All doors are open, so we can come from above and from the left
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[n][m]

# Find a configuration of locked doors that gives exactly T paths
def solve():
    # Start with a small maze
    for n_size in range(1, 51):
        for m_size in range(1, 51):
            # Calculate max paths with all doors open
            max_p = max_paths(n_size, m_size)

            if max_p < T:
                continue  # Need a larger maze

            # Try to find a configuration of locked doors
            # We'll use DFS to explore configurations

            # Create a list of all doors to lock
            doors_to_lock = []
            for i in range(1, n_size + 1):
                for j in range(1, m_size + 1):
                    # Door from (i, j) to (i+1, j)
                    doors_to_lock.append(((i, j), 1))
                    # Door from (i, j) to (i, j+1)
                    doors_to_lock.append(((i, j), 2))

            # Use backtracking to find a configuration that gives T paths
            def backtrack(index, paths, locked):  # index: current door index, paths: current count, locked: set of locked doors
                if paths == T:
                    # Found a solution!
                    print(n_size, m_size)
                    print(len(locked))
                    for door, lock in locked:
                        i, j = door
                        if lock == 1:
                            print(f"{i} {j} {i+1} {j}")  # Lock door from (i, j) to (i+1, j)
                        else:
                            print(f"{i} {j} {i} {j+1}")  # Lock door from (i, j) to (i, j+1)
                    return True

                if paths > T:
                    return False

                if index == len(doors_to_lock):
                    return False

                door, lock = doors_to_lock[index]

                # Try locking this door
                if not locked or door not in locked:
                    locked.add(door)
                    if backtrack(index + 1, paths, locked):
                        return True
                    locked.remove(door)

                # Try not locking this door
                return backtrack(index + 1, paths, locked)

            if backtrack(0, max_p, set()):
                return

