import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    m = int(data[idx + 1])
    idx += 2

    # Store operations in reverse order
    operations = []
    for _ in range(m):
        t = int(data[idx])
        if t == 1:
            l = int(data[idx + 1])
            r = int(data[idx + 2])
            d = int(data[idx + 3])
            operations.append((t, l, r, d))
            idx += 4
        else:
            l = int(data[idx + 1])
            r = int(data[idx + 2])
            mi = int(data[idx + 3])
            operations.append((t, l, r, mi))
            idx += 4

    # Start with an array of zeros
    a = [0] * n

    # Process operations in reverse order
    for i in range(m - 1, -1, -1):
        t, l, r, val = operations[i]
        if t == 1:
            # Reverse addition: subtract d from range [l, r]
            d = val
            for j in range(l - 1, r):
                a[j] -= d
        else:
            # Max query: we need at least one element in [l, r] to be val
            # Try to set the leftmost element to val
            found = False
            for j in range(l - 1, r):
                if a[j] == 0 and not found:
                    a[j] = val
                    found = True

    # Verify all operations
    verify = True
    for i in range(m):
        t, l, r, val = operations[i]
        if t == 1:
            # Check if adding val to [l, r] is consistent
            add = a[l - 1:r]
            expected = [x + val for x in add]
            for j in range(l - 1, r):
                if a[j] != expected[j - (l - 1)]:
                    verify = False
                    break
        else:
            # Check if max in [l, r] is val
            max_val = max(a[l - 1:r])
            if max_val != val:
                verify = False
                break

    if verify:
        print("YES")
        print(' '.join(map(str, a)))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
