import math

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # For each start position, find the maximum end position
    max_len = 0
    result = []

    for i in range(n):
        # For the subarray starting at i, find the longest subarray
        # where there exists an element that divides all elements
        current_gcd = a[i]
        # Maintain a set of elements that divide all elements so far
        divisors = {a[i]}
        j = i

        for k in range(i + 1, n):
            # Update gcd with a[k]
            current_gcd = math.gcd(current_gcd, a[k])

            # Check if current_gcd is divisible by any element in [i, k]
            valid = False

            # Check if current_gcd is divisible by the current element a[k]
            if current_gcd % a[k] == 0:
                valid = True
            else:
                # Check if current_gcd is divisible by any element from divisors
                for val in divisors:
                    if current_gcd % val == 0:
                        valid = True
                        break

            if valid:
                divisors.add(a[k])
                j = k
            else:
                break

        if j - i > max_len:
            max_len = j - i
            result = [i + 1]  # 1-indexed
        elif j - i == max_len:
            result.append(i + 1)

    print(len(result), max_len)
    print(' '.join(map(str, result)))

solve()
