def find_triplet(n):
    # Try pattern: x = n, y = n + 1, z = n(n+1)
    x = n
    y = n + 1
    z = n * (n + 1)

    # Check if 1/x + 1/y + 1/z = 1/n
    # 1/n + 1/(n+1) + 1/(n(n+1)) = 2/n
    if 1/x + 1/y + 1/z == 1/n:
        return (x, y, z)

    # Try pattern: x = n, y = n + 1, z = n(n+1)/2
    z = n * (n + 1) // 2
    if 1/x + 1/y + 1/z == 1/n:
        return (x, y, z)

    # Try brute force search
    for x in range(1, n+1):
        for y in range(x+1, n+1):
            # Calculate what z would need to be
            # 1/x + 1/y + 1/z = 1/n
            # 1/z = 1/n - 1/x - 1/y
            try:
                z = 1 / (1/n - 1/x - 1/y)
                if z.is_integer() and z > 0 and z != x and z != y:
                    return (x, y, int(z))
            except:
                continue

    return -1

n = int(input())
result = find_triplet(n)

if result == -1:
    print(-1)
else:
