{"code": "
import sys

def count_bulls_cows(candidate, guess):
    """Return (bulls, cows) for given candidate and guess"""
    bulls = 0
    cows = 0

    # Count bulls
    for i in range(4):
        if candidate[i] == guess[i]:
            bulls += 1

    # Count cows (digits present in different positions)
    candidate_digits = set(candidate)
    guess_digits = set(guess)

    # Remove bulls from consideration
    for i in range(4):
        if candidate[i] == guess[i]:
            candidate_digits.remove(candidate[i])
            guess_digits.remove(guess[i])

    cows = len(candidate_digits) + len(guess_digits)  # They should be equal

    return bulls, cows

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    n = int(data[0])
    guesses = []

    for line in data[1:n+1]:
        parts = line.split()
        guess = parts[0]
        bulls = int(parts[1])
        cows = int(parts[2])
        guesses.append((guess, bulls, cows))

    # Generate all possible candidates
    candidates = []
    from itertools import permutations
    for digits in permutations(range(10), 4):
        # Convert to string with leading zeros
        candidate = [str(d) for d in digits]
        candidates.append(candidate)

    # Find matching candidates
    matching = []
    for candidate in candidates:
        match = True
        for guess, bulls, cows in guesses:
            c_bulls, c_cows = count_bulls_cows(candidate, guess)
            if c_bulls != bulls or c_cows != cows:
                match = False
                break
        if match:
            matching.append(candidate)

    if len(matching) == 0:
        print("Incorrect data")
    elif len(matching) == 1:
        print(f"{''.join(matching[0])}")
    else:
        print("Need more data")

if __name__ == "__main__":
    solve()
"}

