for _ in range(n):
    s, d = map(int, input().split())
    requests.append((s, d))

occupied = set()
output = []
current_free = 1  # Track the earliest day that is free

for i, (s, d) in enumerate(requests):
    # Check if preferred block is free
    free = True
    for day in range(s, s + d):
        if day in occupied:
            free = False
            break

    if free:
        for day in range(s, s + d):
            occupied.add(day)
        output.append((s, s + d - 1))
        # Update current_free to the first day after this block
        current_free = s + d
    else:
        # Use the earliest free block
        for day in range(current_free, current_free + d):
            occupied.add(day)
        output.append((current_free, current_free + d - 1))
        # Update current_free to the first day after this block
        current_free = current_free + d

for start, end in output:
    print(start, end)
