# Generate all possible 4-digit numbers with distinct digits
possible_numbers = []
for d1 in range(10):
    for d2 in range(10):
        for d3 in range(10):
            for d4 in range(10):
                # Check if all digits are distinct
                if len(set([d1, d2, d3, d4])) == 4:
                    possible_numbers.append(f"{d1}{d2}{d3}{d4}")

# Read input
n = int(input())
guesses = []
for _ in range(n):
    parts = input().split()
    guesses.append((parts[0], int(parts[1]), int(parts[2])))

# For each possible number, check if it fits all guesses
valid_numbers = []
for num in possible_numbers:
    fits = True
    for guess, bulls, cows in guesses:
        # Calculate bulls and cows for this guess
        bull_count = 0
        cow_count = 0
        for i in range(4):
            if num[i] == guess[i]:
                bull_count += 1
        # Calculate cows
        for i in range(4):
            if num[i] != guess[i]:
                if guess[i] in num[:i] + num[i+1:]:
                    cow_count += 1
        if bull_count != bulls or cow_count != cows:
            fits = False
            break
    if fits:
        valid_numbers.append(num)

# Determine result
if len(valid_numbers) == 0:
    print("Incorrect data")
elif len(valid_numbers) == 1:
    print(valid_numbers[0])
else:
    print("Need more data")
"}

