possible_numbers = []
for d1 in range(10):
    for d2 in range(10):
        for d3 in range(10):
            for d4 in range(10):
                if len({d1, d2, d3, d4}) == 4:
                    possible_numbers.append(f"{d1}{d2}{d3}{d4}")

# Read input
n = int(input())
guesses = []
for _ in range(n):
    a, b, c = input().split()
    guesses.append((a, int(b), int(c)))

# Filter possible numbers
for guess, bulls, cows in guesses:
    guess_digits = list(guess)
    filtered = []
    for num in possible_numbers:
        num_digits = list(num)
        # Count bulls
        bull_count = sum(1 for i in range(4) if guess_digits[i] == num_digits[i])
        # Count cows
        cow_count = 0
        # Count digits in guess that are in the number but in different positions
        for i in range(4):
            for j in range(4):
                if i != j and guess_digits[i] == num_digits[j]:
                    cow_count += 1
                    break
        # Remove duplicates from cows count
        cow_set = set()
        for i in range(4):
            for j in range(4):
                if i != j and guess_digits[i] == num_digits[j]:
                    cow_set.add(guess_digits[i])
                    break
        cow_count = len(cow_set)
        # Check if this number is consistent
        if bull_count == bulls and cow_count == cows:
            filtered.append(num)
    possible_numbers = filtered
    # If no numbers left, break
    if not possible_numbers:
        break

if not possible_numbers:
    print("Incorrect data")
elif len(possible_numbers) == 1:
    print(possible_numbers[0])
else:
    print("Need more data")
