def count_distinct_integers(n):
    """Count how many distinct integers can be represented using exactly n roman digits."""

    # For small n, use dynamic programming to count reachable sums
    # For large n, we need a mathematical approach

    # For n <= 100, brute force
    if n <= 100:
        # Track achievable values
        reachable = [False] * (50 * n + 1)
        reachable[0] = True

        for _ in range(n):
            # Create a new set of reachable values
            new_reachable = reachable.copy()
            for value in range(len(reachable)):
                if reachable[value]:
                    for digit_value in [1, 5, 10, 50]:
                        new_reachable[value + digit_value] = True
            reachable = new_reachable

        return sum(reachable)

    # For large n, we need a different approach
    # For n >= 100, we can assume we can get any value between n and 50*n
    # This is a simplification, but let's try it
    return 50 * n - n + 1

n = int(input())
print(count_distinct_integers(n))
