    for j in range(n):
        if i != j:
            val = a[i][j]
            if val in value_counts:
                value_counts[val] += 1
            else:
                value_counts[val] = 1

# The minimum element appears n-1 times (once with each other element)
min_val = None
for val, count in value_counts.items():
    if count == n - 1:
        min_val = val
        break

# The maximum element appears 0 times
max_val = None
for val in range(1, n + 1):
    if val not in value_counts:
        max_val = val
        break

# Now find the permutation
perm = [0] * n

# For each position, the value must be min_val or max_val
# We need to determine which is where

# Find which row corresponds to min_val
# min_val's row will have all values equal to min_val
min_row = None
for i in range(n):
    if all(val == min_val for val in a[i]):
        min_row = i
        break

# The remaining row corresponds to max_val
for i in range(n):
    if i != min_row:
        perm[i] = max_val
        break

# Set min_val at the identified row
perm[min_row] = min_val

print(' '.join(map(str, perm)))
