for i in range(n):
    for j in range(n):
        if i != j:
            val = a[i][j]
            if val in value_counts:
                value_counts[val] += 1
            else:
                value_counts[val] = 1

# Find the minimum value (appears n-1 times)
min_val = None
for val, count in value_counts.items():
    if count == n - 1:
        min_val = val
        break

# Find the maximum value (appears 0 times)
max_val = None
for val in range(1, n + 1):
    if val not in value_counts:
        max_val = val
        break

# Now find the permutation
perm = [0] * n

# For each position, find the value that can be placed there
for i in range(n):
    # Try to find a value that appears in the row
    for val in range(1, n + 1):
        # Check if val is already used
        if val in perm:
            continue

        # Check if val can be placed at position i
        valid = True
        for j in range(n):
            if i == j:
                continue
            # If val is placed at i, then min(val, perm[j]) should match a[i][j]
            if val == perm[j]:
                if a[i][j] != val:
                    valid = False
                    break
            elif val > perm[j]:
                if a[i][j] != perm[j]:
                    valid = False
                    break
            elif val < perm[j]:
                if a[i][j] != val:
                    valid = False
                    break

        if valid:
            perm[i] = val
            break

print(' '.join(map(str, perm)))

