# Brute force: try all subsets
# This is only for understanding, not for actual solution

max_cost = 0

for mask in range(1 << n):
    # Check if this subset is strange
    is_strange = True
    for i in range(n):
        if (mask >> i) & 1:
            # i is included
            for j in range(i):
                if (mask >> j) & 1:
                    # j is also included
                    if a[j] % a[i] == 0:
                        # a_j divides a_i
                        continue
                else:
                    if a[j] % a[i] == 0:
                        # a_j divides a_i but j is not included
                        is_strange = False
                        break
            if not is_strange:
                break

    if is_strange:
        cost = sum(b[i] for i in range(n) if (mask >> i) & 1)
        max_cost = max(max_cost, cost)

print(max_cost)
