# Read the spanning tree
spanning_tree = []
for _ in range(n - 1):
    u, v = map(int, input().split())
    spanning_tree.append((u, v))

# The key insight: In a tree with n nodes, any Hamiltonian path must use at least
# (n-2) tree edges to connect all nodes. The remaining 1 edge can be a non-tree edge.

# Special case for n = 2:
if n == 2:
    if x < y:
        result = x
    else:
        result = y
else:
    # For n > 2:
    if x < y:
        # Use n-2 tree edges + 1 non-tree edge
        result = (n - 2) * x + y
    else:
        # Use all non-tree edges
        result = (n - 1) * y

print(result)
