import sys
import math

def solve(a, b):
    total = a + b
    min_perimeter = float('inf')

    # Find all factor pairs of total where w <= h
    for w in range(1, int(math.isqrt(total)) + 1):
        if total % w == 0:
            h = total // w
            # Check if a can fit in w x h
            can_a_fit = False
            for d in range(1, int(math.isqrt(a)) + 1):
                if a % d == 0:
                    if d <= w and (a // d) <= h:
                        can_a_fit = True
                        break
            if not can_a_fit:
                for d in range(1, int(math.isqrt(a)) + 1):
                    if a % d == 0:
                        if (a // d) <= w and d <= h:
                            can_a_fit = True
                            break

            # Check if b can fit in w x h
            can_b_fit = False
            for d in range(1, int(math.isqrt(b)) + 1):
                if b % d == 0:
                    if d <= w and (b // d) <= h:
                        can_b_fit = True
                        break
            if not can_b_fit:
                for d in range(1, int(math.isqrt(b)) + 1):
                    if b % d == 0:
                        if (b // d) <= w and d <= h:
                            can_b_fit = True
                            break

            if can_a_fit or can_b_fit:
                perimeter = 2 * (w + h)
                min_perimeter = min(min_perimeter, perimeter)

    return min_perimeter

def main():
    data = sys.stdin.read().strip().split()
    a = int(data[0])
    b = int(data[1])
    result = solve(a, b)
    print(result)

if __name__ == "__main__":
    main()
"}

