import sys

def solve():
    MOD = 998244353
    n = int(sys.stdin.readline())
    tree = [[] for _ in range(n + 1)]

    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        tree[u].append(v)
        tree[v].append(u)

    # Check if the tree is a star (one node with degree n-1)
    center = -1
    for i in range(1, n + 1):
        if len(tree[i]) == n - 1:
            center = i
            break

    if center != -1:
        # If it's a star, all permutations are valid
        print((n * (n - 1) * (n - 2) * (n - 3)) % MOD)
    else:
        # For complex trees, only certain permutations are valid
        # Let's count the number of valid permutations
        # This is more complex, let's think about it

        # For a tree that's not a star, maybe the answer is n * 2^{n-2}
        # Let's test with the examples

