    a = list(map(int, input().split()))

    # Build the permutation graph
    # For each value, find where it should go

    pos = [0] * (n + 1)
    for i in range(n):
        pos[a[i]] = i

    # Find cycles
    visited = [False] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i]:
            visited[i] = True
            j = pos[i]
            while j != i:
                visited[j] = True
                j = pos[j]

    # Count number of cycles
    cycle_count = 0
    for i in range(1, n + 1):
        if not visited[i]:
            cycle_count += 1

    print(cycle_count)
