            # We'll start with no locked doors

            # Calculate the number of paths in a full grid
            full_paths = 1
            for i in range(n + m - 2):
                full_paths *= (n + m - 2 - i)
                full_paths //= (i + 1)

            # If full_paths == T, return grid with no locked doors
            if full_paths == T:
                print(f"{n} {m}")
                print(0)
                return

            # If full_paths < T, we need to unlock doors (but we can't unlock doors we already locked)
            # Since we start with all doors unlocked, full_paths is the maximum
            # So we can't have full_paths < T with no locked doors
            # Therefore, we need to lock doors to reduce the count to T

            # Lock doors to reduce the count
            # We'll lock doors systematically

            # Lock doors to the right
            for i in range(1, n + 1):
                for j in range(1, m):
                    # Lock door to the right

                    # Recalculate paths
                    new_paths = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
                    new_paths[1][1] = 1

