    it = iter(input)
    t = int(next(it))
    for _ in range(t):
        n = int(next(it))
        a = int(next(it))
        b = int(next(it))
        graph = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(next(it))
            v = int(next(it))
            graph[u].append(v)
            graph[v].append(u)

        def bfs(start):
            dist = [0] * (n + 1)
            visited = [False] * (n + 1)
            q = deque([start])
            visited[start] = True
            while q:
                node = q.popleft()
                for nei in graph[node]:
                    if not visited[nei]:
                        visited[nei] = True
                        dist[nei] = dist[node] + 1
                        q.append(nei)
            return dist

        da = bfs(a)
        db = bfs(b)
        L = da[b]  # distance from a to b

        # Find a vertex u not on the path from a to b such that da[u] == db[u]
        found = False
        for v in range(1, n + 1):
            if v == a or v == b:
                continue
            # Check if v is on the path from a to b
            if da[v] + db[v] == L:
                # v is on the path; its neighbors might be off-path
                # We need to check neighbors of v that are not on the path
                for nei in graph[v]:
