def distance_squared(x1, y1, x2, y2):
    """Calculate squared distance between two points."""
    dx = x1 - x2
    dy = y1 - y2
    return dx * dx + dy * dy


def count_overlap(circles):
    """Count how many circles overlap at each point."""
    # Store: key = (x, y), value = count of circles covering this point
    coverage = {}

    # Check all pairs of circles
    for i in range(len(circles)):
        (xi, yi) = circles[i]
        # Check all other circles
        for j in range(len(circles)):
            if i == j:
                continue
            (xj, yj) = circles[j]

            # Calculate distance squared
            dist_sq = distance_squared(xi, yi, xj, yj)

            # If circles overlap (distance < 2)
            if dist_sq < 4.0:
                # Check all points in the intersection of these two circles
                # We'll check points at integer coordinates within both circles
                # This is a simplification - we should check continuous points
                # But for now, let's just check if any point within both circles
                # is covered by other circles

                # Find integer coordinates that are inside both circles
                for x in range(int(xi - 1) - 1, int(xi + 1) + 2):
                    for y in range(int(yi - 1) - 1, int(yi + 1) + 2):
                        # Check if (x, y) is inside both circles
                        inside1 = (xi - 1 <= x <= xi + 1) and (yi - 1 <= y <= yi + 1)
                        inside2 = (xj - 1 <= x <= xj + 1) and (yj - 1 <= y <= yj + 1)

                        if inside1 and inside2:
                            # Count how many circles cover this point
                            count = 1  # at least these two circles
                            for k in range(len(circles)):
                                if k == i or k == j:
                                    continue
                                (xk, yk) = circles[k]
                                if (xk - 1 <= x <= xk + 1) and (yk - 1 <= y <= yk + 1):
                                    count += 1

                            coverage[(x, y)] = count

    if coverage:
        return max(coverage.values())
    return 1  # At least one circle


def solve():
    while True:
        line = input().strip()
        if not line:
            continue

        n = int(line)
        if n == 0:
            break

        circles = []
        for _ in range(n):
            coords = input().strip().split(', ')
            x = float(coords[0])
            y = float(coords[1])
            circles.append((x, y))

        result = count_overlap(circles)
        print(result)

