import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    A = []
    for i in range(n):
        row = [int(next(it)) for _ in range(n)]
        A.append(row)

    # Calculate initial answer
    ans = 0
    for i in range(n):
        for j in range(n):
            if A[i][j] == 1 and A[j][i] == 1:
                ans += 1

    q = int(next(it))
    res = []

    for _ in range(q):
        t = next(it)
        if t == '1':
            # Flip row i
            i = int(next(it)) - 1
            for j in range(n):
                # Before flip
                if A[i][j] == 1 and A[j][i] == 1:
                    ans -= 1
                # Flip
                A[i][j] ^= 1
                # After flip
                if A[i][j] == 1 and A[j][i] == 1:
                    ans += 1
        elif t == '2':
            # Flip column i
            i = int(next(it)) - 1
            for j in range(n):
                # Before flip
                if A[j][i] == 1 and A[i][j] == 1:
                    ans -= 1
                # Flip
                A[j][i] ^= 1
                # After flip
                if A[j][i] == 1 and A[i][j] == 1:
                    ans += 1
        elif t == '3':
            res.append(str(ans % 2))

    sys.stdout.write(''.join(res))

if __name__ == '__main__':
    main()
