    # We need to ensure we don't have a situation where a pirate with 2 coins is next to a pirate with 0 coins
    # and the other neighbor has 1 coin
    has_cycle = False
    for i in range(1, n + 1):
        left = pirates[i - 1] if i - 1 >= 1 else pirates[n]
        right = pirates[i + 1] if i + 1 <= n else pirates[1]
        if pirates[i] >= 2:
            if left == 0 and right == 1:
                has_cycle = True
                break
            if right == 0 and left == 1:
                has_cycle = True
                break

    if has_cycle:
        print(-1)
    else:
        print(1)
