def solve():
    n = int(input())
    p = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Create graph of (position, direction) pairs
    # (i, d) -> (p[i-1], 1-d) if b[i-1] == 1 else (p[i-1], d)
    graph = {}
    for i in range(n):
        position = i + 1
        d0 = 0
        d1 = 1
        # From (position, 0)
        if b[i] == 1:
            graph[(position, d0)] = (p[i], d1)
        else:
            graph[(position, d0)] = (p[i], d0)
        # From (position, 1)
        if b[i] == 1:
            graph[(position, d1)] = (p[i], d0)
        else:
            graph[(position, d1)] = (p[i], d1)

    # Check if we can reach (i, 0) from (i, 1)
    can_reach_i0_from_i1 = [False] * n
    # Check if we can reach (i, 1) from (i, 0)
    can_reach_i1_from_i0 = [False] * n

    # Create 2D arrays to track reachability
    can_reach_j0_from_i0 = [[False] * n for _ in range(n)]
    can_reach_j1_from_i1 = [[False] * n for _ in range(n)]

    # Use BFS from each starting point
    for start in range(n):
        # BFS from (start+1, 0)
        visited = set()
        queue = [(start+1, 0)]
        visited.add((start+1, 0))
        while queue:
            pos, direction = queue.pop(0)
            # Mark this position with current direction as reachable
            if pos - 1 >= 0:
                if not can_reach_j0_from_i0[start][pos-1]:
                    can_reach_j0_from_i0[start][pos-1] = True
            if direction == 0:
                if not can_reach_i0_from_i1[start]:
                    can_reach_i0_from_i1[start] = True
            else:
                if not can_reach_i1_from_i0[start]:
                    can_reach_i1_from_i0[start] = True
            # Get next state
            next_pos, next_dir = graph[(pos, direction)]
            if (next_pos, next_dir) not in visited:
                visited.add((next_pos, next_dir))
                queue.append((next_pos, next_dir))

        # BFS from (start+1, 1)
        visited = set()
        queue = [(start+1, 1)]
        visited.add((start+1, 1))
        while queue:
            pos, direction = queue.pop(0)
            # Mark this position with current direction as reachable
            if pos - 1 >= 0:
                if not can_reach_j1_from_i1[start][pos-1]:
                    can_reach_j1_from_i1[start][pos-1] = True
            if direction == 0:
                if not can_reach_i1_from_i0[start]:
                    can_reach_i1_from_i0[start] = True
            else:
                if not can_reach_i0_from_i1[start]:
                    can_reach_i0_from_i1[start] = True
            # Get next state
            next_pos, next_dir = graph[(pos, direction)]
            if (next_pos, next_dir) not in visited:
                visited.add((next_pos, next_dir))
                queue.append((next_pos, next_dir))

    # Find a position that can reach all other positions with both directions
    good_positions = []
    for i in range(n):
        # Check if we can reach (i, 0) and (i, 1) from i
        if can_reach_i0_from_i1[i] and can_reach_i1_from_i0[i]:
            # Check if we can reach all positions
