    if area % i == 0:
        j = area // i
        # Check if a can fit in i x j
        # a <= i * j is always true
        # Check if there exists d such that d <= i and a/d <= j
        found_a = False
        for d in range(1, int(math.isqrt(a)) + 1):
            if a % d == 0:
                if d <= i and a // d <= j:
                    found_a = True
                    break
        # Check if b can fit in i x j
        found_b = False
        for d in range(1, int(math.isqrt(b)) + 1):
            if b % d == 0:
                if d <= i and b // d <= j:
                    found_b = True
                    break

        if found_a or found_b:
            perimeter = 2 * (i + j)
            min_perimeter = min(min_perimeter, perimeter)

