# Read input
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = []
        for _ in range(n):
            a.append(int(next(it)))

        # Find positions with books
        positions = [i + 1 for i, val in enumerate(a) if val == 1]

        # If only one book, no moves needed
        if len(positions) == 1:
            print(0)
            continue

        # Find the minimum gap between books
        min_gap = float('inf')
        for i in range(len(positions) - 1):
            gap = positions[i+1] - positions[i] - 1
            if gap < min_gap:
                min_gap = gap

        print(min_gap)

if __name__ == "__main__":
    solve()
"}

