h, w = map(int, input().split())

# Read grid and compute prefix sums for rows
prefix_row = [ [0] * (w + 1) for _ in range(h + 1) ]
for r in range(1, h + 1):
    row = input().strip()
    for c in range(1, w + 1):
        if row[c-1] == '.':
            prefix_row[r][c] = prefix_row[r][c-1] + 1
        else:
            prefix_row[r][c] = prefix_row[r][c-1]

# Read grid and compute prefix sums for columns
prefix_col = [ [0] * (h + 1) for _ in range(w + 1) ]
for c in range(1, w + 1):
    for r in range(1, h + 1):
        if prefix_row[r][c] > prefix_row[r][c-1]:  # Cell (r,c) is '.'
            prefix_col[c][r] = prefix_col[c][r-1] + 1
        else:
            prefix_col[c][r] = prefix_col[c][r-1]

q = int(input())
for _ in range(q):
    r1, c1, r2, c2 = map(int, input().split())

    # Count horizontal dominoes (in rows from r1 to r2-1)
    horizontal = 0
    for r in range(r1, r2):
        horizontal += prefix_row[r][c2] - prefix_row[r][c1-1]

    # Count vertical dominoes (in columns from c1 to c2-1)
    vertical = 0
    for c in range(c1, c2):
        vertical += prefix_col[c][r2] - prefix_col[c][r1-1]

    print(horizontal + vertical)
