for _ in range(n):
    s, d = map(int, input().split())

    # Check if preferred days are available
    available = True
    for day in range(s, s + d):
        if day in occupied:
            available = False
            break

    if available:
        # Use preferred days
        start = s
        end = s + d - 1
        for day in range(start, end + 1):
            occupied.add(day)
        print(start, end)
    else:
        # Find the earliest available slot
        found = False
        start = 1
        while not found:
            # Check if days start to start+d-1 are all available
            available = True
            for day in range(start, start + d):
                if day in occupied:
                    available = False
                    break

            if available:
                found = True
                end = start + d - 1
                for day in range(start, end + 1):
                    occupied.add(day)
                print(start, end)
            else:
                start += 1
